using System;
using System.Linq;
using UnityEngine;
public sealed class GridShiftFinance:MonoBehaviour {
 GridShiftCompany company;DeliveryManager manager;CompanyCampaignState S=>company.State;
 public void Initialize(){company=GetComponent<GridShiftCompany>();manager=company.Manager;if(S.lastFinanceDay==0)S.lastFinanceDay=company.Day;if(S.bills.Count==0&&S.closedWeeks==0)Bill("registration","Registro comercial fictício","Serviços",10,company.Day+3,1);}
 public bool Has(string id)=>company.State.ledger.Any(t=>t.id==id);
 public void Record(string id,float amount,string category,string description){S.ledger.Add(new CompanyTransaction{id=id,amount=amount,category=category,description=description,day=company.Day});}
 public void Bill(string id,string description,string category,float amount,double due,int week){if(amount<=0||S.bills.Any(b=>b.id==id))return;S.bills.Add(new CompanyBill{id=id,description=description,category=category,amount=Mathf.Round(amount*100)/100,dueDay=due,week=week});company.NotifyChanged();}
 void Accrue(double until){double elapsed=Math.Max(0,until-S.lastFinanceDay);foreach(var e in S.employees)if(e.hired)e.payrollAccrued+=(float)(elapsed*e.salary/7);S.lastFinanceDay=Math.Max(S.lastFinanceDay,until);}
 public void Tick(){int target=Math.Max(0,(int)Math.Floor(company.Day/7));int limit=Math.Min(target,S.closedWeeks+52);while(S.closedWeeks<limit){int week=S.closedWeeks+1;Accrue(week*7);CloseWeek(week);}if(S.closedWeeks>=target)Accrue(company.Day);foreach(var b in S.bills)if(!b.paid&&!b.penalized&&company.Day>b.dueDay){b.penalized=true;bool managerHired=S.employees.Any(e=>e.hired&&e.role=="Gerente");b.lateFee=Mathf.Min(5,b.amount*company.Balance.lateFeeRate*(managerHired?.5f:1));company.Reputation(-1);manager.Notify("Conta vencida · "+b.description+". Multa única moderada.");company.Save();}company.FinishServices();}
 string ExpenseCategory(CompanyTransaction t){if(t.category!="Pagamento conta")return t.category;return S.bills.FirstOrDefault(b=>"bill:"+b.id==t.id)?.category??t.category;}
 public void CloseWeek(int week){if(week!=S.closedWeeks+1||company.Day<week*7)return;double start=(week-1)*7,end=week*7;var tx=S.ledger.Where(t=>t.day>=start&&t.day<end).ToArray();float revenue=tx.Where(t=>t.amount>0&&t.category!="Capital"&&t.category!="Crédito de retomada").Sum(t=>t.amount);float expenses=-tx.Where(t=>t.amount<0).Sum(t=>t.amount);double due=end+company.Balance.billGraceDays;
 Bill("rent:"+week,"Aluguel do Office · semana "+week,"Aluguel",company.Balance.officeRent,due,week);Bill("electric:"+week,"Energia · semana "+week,"Energia",company.Balance.electricity,due,week);Bill("services:"+week,"Serviços administrativos · semana "+week,"Serviços",company.Balance.services,due,week);Bill("tax:"+week,"Tributo fictício de gameplay · semana "+week,"Tributos fictícios",revenue*company.Balance.fictionalTaxRate,due,week);
 foreach(var e in S.employees){Bill("salary:"+week+":"+e.id,"Salário proporcional · "+e.name,"Salários",e.payrollAccrued,due,week);e.payrollAccrued=0;}
 S.weeks.Add(new CompanyWeek{week=week,revenue=revenue,expenses=expenses,profit=revenue-expenses,balance=manager.Money,invoiced=S.bills.Where(b=>b.week==week).Sum(b=>b.amount),deliveries=tx.Where(t=>t.category=="Entregas"&&t.amount>0).Sum(t=>t.amount),contracts=tx.Where(t=>t.category=="Contratos"&&t.amount>0).Sum(t=>t.amount),otherIncome=tx.Where(t=>t.category=="Missões"&&t.amount>0).Sum(t=>t.amount),salaries=-tx.Where(t=>ExpenseCategory(t)=="Salários"&&t.amount<0).Sum(t=>t.amount),fuel=-tx.Where(t=>ExpenseCategory(t)=="Combustível"&&t.amount<0).Sum(t=>t.amount),rent=-tx.Where(t=>ExpenseCategory(t)=="Aluguel"&&t.amount<0).Sum(t=>t.amount),maintenance=-tx.Where(t=>ExpenseCategory(t)=="Manutenção"&&t.amount<0).Sum(t=>t.amount),taxes=-tx.Where(t=>ExpenseCategory(t)=="Tributos fictícios"&&t.amount<0).Sum(t=>t.amount),services=-tx.Where(t=>(ExpenseCategory(t)=="Serviços"||ExpenseCategory(t)=="Energia"||ExpenseCategory(t)=="Contratação")&&t.amount<0).Sum(t=>t.amount),upgrades=-tx.Where(t=>ExpenseCategory(t)=="Upgrades"&&t.amount<0).Sum(t=>t.amount)});S.closedWeeks=week;manager.Notify("Fechamento da semana "+week+" disponível no Financeiro. Contas vencem em "+company.Balance.billGraceDays+" dias.");company.Save();}
 public bool Pay(string id,out string error){error=null;var b=S.bills.FirstOrDefault(x=>x.id==id);if(b==null){error="Conta inexistente.";return false;}if(b.paid){error="Esta conta já está paga.";return false;}Tick();if(!manager.TryChangeMoney(-(b.amount+b.lateFee),"bill:"+id,"Pagamento conta",b.category+" · "+b.description)){error="Saldo insuficiente. Faça entregas, renegocie ou consulte a retomada.";return false;}b.paid=true;company.NotifyChanged();company.Save();return true;}
 public bool Defer(string id,out string error){error=null;var b=S.bills.FirstOrDefault(x=>x.id==id);if(b==null||b.paid||b.deferred){error="Conta paga, inexistente ou já renegociada.";return false;}b.deferred=true;b.dueDay=Math.Max(company.Day,b.dueDay)+3;company.NotifyChanged();company.Save();return true;}
 public bool Recovery(out string error){error=null;if(manager.Money>=20||company.Day<S.nextRecoveryDay){error="Retomada disponível com saldo menor que R$ 20, uma vez a cada sete dias.";return false;}string id="recovery:"+Guid.NewGuid().ToString("N");if(!manager.TryChangeMoney(60,id,"Crédito de retomada","Apoio fictício sem juros")){error="Crédito indisponível.";return false;}Bill(id,"Devolução do apoio de retomada","Retomada",60,company.Day+10,(int)(company.Day/7)+1);S.nextRecoveryDay=company.Day+7;company.Save();return true;}
}

